/**
 * Dark Room (TPI-V2-WEB-010 §11/§12/§13, Phase 010C).
 *
 * Port of `Photography/PPPhotoCaseAnalysisView.swift` (list, import, flag) and
 * `Photography/PPPhotoDetailView.swift` (adjustments, notes):
 *   "Dark Room Adjustments (Preview Only)" — Brightness −0.4…0.4,
 *   Contrast 0.6…1.8, Black & White, Include in Findings, Notes + Save Notes.
 *
 * Integrity: the imported original is stored unchanged through the evidence
 * pipeline. Adjustments are preview-only; saving creates a DERIVATIVE that
 * records the exact parameters. No image is ever overwritten, and no visual
 * anomaly is fabricated or labelled.
 */
import "../dashboard/dashboard.css";
import { getDb } from "../../core/db";
import { EvidenceRepository } from "../../core/repositories/evidenceRepository";
import { AuditService } from "../../core/audit";
import { getManagedFileStore } from "../../core/files/storeRegistry";
import { esc, viewShell, wireBackButton } from "../dashboard/shell";
import { mountView, onDelegate, invalidateView } from "../../shared/uidom";
import { navigate } from "../../app/router";

const db = () => getDb();

/** Original slider ranges (PPPhotoDetailView). */
export const BRIGHTNESS_RANGE = { min: -0.4, max: 0.4, default: 0 } as const;
export const CONTRAST_RANGE = { min: 0.6, max: 1.8, default: 1 } as const;

interface PhotoUiState {
  selectedId: string | null;
  brightness: number;
  contrast: number;
  blackAndWhite: boolean;
  includeInFindings: boolean;
  notes: string;
  status: string;
  objectUrls: string[];
  /** Decoded source image, kept for re-rendering the preview. */
  image: HTMLImageElement | null;
}

const ui = new WeakMap<HTMLElement, PhotoUiState>();

function st(container: HTMLElement): PhotoUiState {
  let s = ui.get(container);
  if (!s) {
    s = {
      selectedId: null,
      brightness: BRIGHTNESS_RANGE.default,
      contrast: CONTRAST_RANGE.default,
      blackAndWhite: false,
      includeInFindings: false,
      notes: "",
      status: "",
      objectUrls: [],
      image: null,
    };
    ui.set(container, s);
  }
  return s;
}

function releaseUrls(s: PhotoUiState): void {
  for (const url of s.objectUrls) URL.revokeObjectURL(url);
  s.objectUrls = [];
}

/**
 * Apply the Dark Room adjustments to a canvas — exact port of the original
 * preview maths (brightness as an additive offset, contrast around mid-grey).
 */
export function applyPhotoAdjustments(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  opts: { brightness: number; contrast: number; blackAndWhite: boolean },
): void {
  if (width <= 0 || height <= 0) return;
  const data = ctx.getImageData(0, 0, width, height);
  const px = data.data;
  const brightness = opts.brightness * 255; // −0.4…0.4 → ±102 levels, as iOS
  const contrast = opts.contrast;
  for (let i = 0; i < px.length; i += 4) {
    let r = px[i] ?? 0;
    let g = px[i + 1] ?? 0;
    let b = px[i + 2] ?? 0;
    if (opts.blackAndWhite) {
      const luma = 0.2126 * r + 0.7152 * g + 0.0722 * b;
      r = luma;
      g = luma;
      b = luma;
    }
    r = (r - 128) * contrast + 128 + brightness;
    g = (g - 128) * contrast + 128 + brightness;
    b = (b - 128) * contrast + 128 + brightness;
    px[i] = Math.max(0, Math.min(255, r));
    px[i + 1] = Math.max(0, Math.min(255, g));
    px[i + 2] = Math.max(0, Math.min(255, b));
  }
  ctx.putImageData(data, 0, 0);
}

export async function renderDarkRoom(container: HTMLElement, evidenceId?: string): Promise<void> {
  const s = st(container);
  if (evidenceId) s.selectedId = evidenceId;

  const photos = (await db().evidence.toArray())
    .filter((e) => e.mediaType === "photo" && e.kind === "original")
    .sort((a, b) => b.createdAt - a.createdAt);
  if (!s.selectedId && photos.length > 0) s.selectedId = photos[0]!.id;
  const selected = photos.find((p) => p.id === s.selectedId);

  releaseUrls(s);
  s.image = null;
  // Thumbnails: object URL per photo (revoked on the next render).
  const thumbUrls = new Map<string, string>();
  for (const photo of photos.slice(0, 50)) {
    try {
      const bytes = await getManagedFileStore().read(photo.opfsPath);
      if (!bytes) continue;
      const url = URL.createObjectURL(new Blob([bytes], { type: photo.mimeType ?? "image/*" }));
      s.objectUrls.push(url);
      thumbUrls.set(photo.id, url);
    } catch {
      /* thumbnail unavailable — the row still lists the record */
    }
  }
  if (selected) {
    const url = thumbUrls.get(selected.id);
    if (url) {
      const image = new Image();
      image.src = url;
      await image.decode().catch(() => undefined);
      s.image = image;
    } else {
      s.status = "The managed copy is not present in browser storage.";
    }
  }

  const cases = await caseList();
  invalidateView(container);
  mountView(
    container,
    viewShell(
      "Dark Room",
      `
      <div class="case-form" data-root="dark-room" data-epoch="${Date.now()}-${Math.random()}">
        <h3 class="cc-section-title">Import Photo</h3>
        <div class="detail-grid">
          <div class="detail-field"><label for="dr-case">Case</label>
            <select id="dr-case">
              ${cases.length === 0 ? '<option value="">— no cases yet —</option>' : cases.map((c) => `<option value="${c.id}">${esc(c.caseNumber)} — ${esc(c.title)}</option>`).join("")}
            </select></div>
          <div class="detail-field"><label for="dr-room">Room (optional)</label>
            <select id="dr-room"><option value="">Unassigned</option></select></div>
        </div>
        <div class="detail-field"><label for="dr-files">Images (multiple allowed)</label>
          <input id="dr-files" type="file" accept="image/*" multiple></div>
        <div class="form-actions">
          <button class="button-primary" id="dr-import" type="button">Import Photo</button>
          <button class="button-secondary" id="dr-capture" type="button">Capture from Camera…</button>
        </div>
        <p class="cc-meta" id="dr-status" role="status">${esc(s.status)}</p>
        <p class="cc-meta">Imported photos are stored unchanged (original bytes, SHA-256 hashed). Camera access depends on the browser and device; <strong>Import Photo</strong> always works as the fallback.</p>

        <h3 class="cc-section-title">Case Photos (${photos.length})</h3>
        ${
          photos.length === 0
            ? '<div class="cc-empty">No photos imported. Import photos to this case, then open each item for dark room review and flagging.</div>'
            : photos
                .map((p) => {
                  const url = thumbUrls.get(p.id) ?? "";
                  return `
            <div class="case-row" data-photo="${p.id}">
              <div style="display:flex;gap:12px;align-items:center;">
                ${url ? `<img src="${url}" alt="" width="66" height="66" style="object-fit:cover;border-radius:10px;border:1px solid var(--border);">` : '<div aria-hidden="true" style="width:66px;height:66px;border-radius:10px;border:1px solid var(--border);background:var(--background-deep);"></div>'}
                <div>
                  <div class="case-title">${esc(p.title || "Imported Photo")}</div>
                  <div class="case-meta">${new Date(p.createdAt).toLocaleString()}${p.reviewStatus === "flagged" || p.reviewStatus === "reviewed" ? ' • <strong>Included in Findings</strong>' : ""}</div>
                </div>
              </div>
              <button class="back-button" data-open-photo="${p.id}" type="button">Open</button>
            </div>`;
                })
                .join("")
        }

        ${
          selected
            ? `
        <h3 class="cc-section-title">Dark Room Adjustments (Preview Only)</h3>
        <div class="case-form" data-photo-editor="${selected.id}">
          <div class="detail-grid">
            <div class="detail-field"><label for="dr-brightness">Brightness (${BRIGHTNESS_RANGE.min}…${BRIGHTNESS_RANGE.max})</label>
              <input id="dr-brightness" type="range" min="${BRIGHTNESS_RANGE.min}" max="${BRIGHTNESS_RANGE.max}" step="0.01" value="${s.brightness}">
              <div class="case-meta" id="dr-brightness-value">${s.brightness.toFixed(2)}</div></div>
            <div class="detail-field"><label for="dr-contrast">Contrast (${CONTRAST_RANGE.min}…${CONTRAST_RANGE.max})</label>
              <input id="dr-contrast" type="range" min="${CONTRAST_RANGE.min}" max="${CONTRAST_RANGE.max}" step="0.01" value="${s.contrast}">
              <div class="case-meta" id="dr-contrast-value">${s.contrast.toFixed(2)}</div></div>
          </div>
          <div class="detail-field"><label class="cc-count"><input type="checkbox" id="dr-bw" ${s.blackAndWhite ? "checked" : ""}> Black &amp; White</label></div>
          <div class="detail-field"><label class="cc-count"><input type="checkbox" id="dr-findings" ${selected.reviewStatus === "flagged" || s.includeInFindings ? "checked" : ""}> Include in Findings</label></div>

          <div style="margin:12px 0;">
            <canvas id="dr-preview" width="900" height="560" style="width:100%;max-height:60vh;background:#0B0E12;border:1px solid #2A3441;border-radius:8px;object-fit:contain;" aria-label="Dark Room preview"></canvas>
          </div>
          <div class="form-actions">
            <button class="button-primary" id="dr-save-derivative" type="button">Save Adjusted Copy to Case</button>
            <button class="back-button" id="dr-reset-adjust" type="button">Reset Adjustments</button>
          </div>

          <h3 class="cc-section-title">Notes</h3>
          <div class="detail-field"><label for="dr-notes">Investigator notes</label>
            <textarea id="dr-notes" rows="3">${esc(selected.notes ?? s.notes)}</textarea></div>
          <div class="form-actions"><button class="button-secondary" id="dr-save-notes" type="button">Save Notes</button></div>
          <p class="cc-meta">Notes and flags are stored as investigator assessment. Ambiguous shapes are <strong>not</strong> labelled as paranormal evidence — record what you observe and what you considered as an explanation.</p>
          <div class="case-form">
            <div class="case-title">Source</div>
            <div class="case-meta">${esc(selected.originalFileName ?? selected.fileName)} • ${Math.round(selected.fileSizeBytes / 1024)} KB • SHA-256 ${esc(selected.contentHash.slice(0, 24))}… • integrity ${esc(selected.verificationStatus ?? "unverified")}</div>
          </div>
        </div>`
            : ""
        }

        <div class="form-actions"><button class="back-button" id="dr-back" type="button">← Back</button></div>
      </div>
    `,
  ));

  if (s.image && s.image.complete && s.image.naturalWidth > 0) {
    const canvas = container.querySelector<HTMLCanvasElement>("#dr-preview");
    const ctx = canvas?.getContext("2d");
    if (canvas && ctx) {
      const scale = Math.min(canvas.width / s.image.naturalWidth, canvas.height / s.image.naturalHeight);
      const w = Math.floor(s.image.naturalWidth * scale);
      const h = Math.floor(s.image.naturalHeight * scale);
      canvas.width = w;
      canvas.height = h;
      ctx.drawImage(s.image, 0, 0, w, h);
      applyPhotoAdjustments(ctx, w, h, {
        brightness: s.brightness,
        contrast: s.contrast,
        blackAndWhite: s.blackAndWhite,
      });
    }
  }

  await populateRooms(container, s);
  wireHandlers(container, s);
  wireBackButton(container);
}

/** Case list for the import selector. */
async function caseList(): Promise<Array<{ id: string; caseNumber: string; title: string }>> {
  const { CaseRepository } = await import("../../core/repositories/caseRepository");
  const cases = await new CaseRepository(db()).listCases(200);
  return cases.map((c) => ({ id: c.id, caseNumber: c.caseNumber, title: c.title }));
}

async function populateRooms(container: HTMLElement, s: PhotoUiState): Promise<void> {
  const caseSelect = container.querySelector<HTMLSelectElement>("#dr-case");
  const roomSelect = container.querySelector<HTMLSelectElement>("#dr-room");
  if (!caseSelect || !roomSelect) return;
  const caseId = caseSelect.value;
  if (!caseId) return;
  const structure = await db().propertyStructures.where("caseId").equals(caseId).first();
  const rooms = structure
    ? (await db().structureRooms.where("structureId").equals(structure.id).toArray()).filter((r) => !r.archived)
    : [];
  roomSelect.innerHTML = `<option value="">Unassigned</option>${rooms.map((r) => `<option value="${r.id}"${s.selectedId && r.id === "" ? " selected" : ""}>${esc(r.name)}</option>`).join("")}`;
}

function wireHandlers(container: HTMLElement, s: PhotoUiState): void {
  const reload = () => renderDarkRoom(container, s.selectedId ?? undefined);

  onDelegate(container, "click", "#dr-back", () => navigate("forensic"));
  onDelegate(container, "change", "#dr-case", () => void populateRooms(container, s));

  const importPhotos = async (files: File[], caseId: string, roomId: string | null) => {
    const repo = new EvidenceRepository(db());
    let imported = 0;
    for (const file of files) {
      const record = await repo.storeOriginal({
        caseId,
        mediaType: "photo",
        title: file.name.replace(/\.[^.]+$/, "") || "Imported Photo",
        fileName: file.name,
        data: file,
        origin: "photo-import",
        recordedBy: "local-user",
      });
      await db().evidence.put({
        ...record,
        originalFileName: file.name,
        sourceDescription: "Imported photo",
        importedAt: Date.now(),
        verificationStatus: "verified",
        verifiedAt: Date.now(),
        verificationDetail: "Stored unchanged on import and hashed.",
        roomId,
        captureTimestamp: file.lastModified || null,
        captureTimestampSource: file.lastModified ? "fileMetadata" : "unknown",
      });
      imported += 1;
    }
    s.status = `${imported} photo(s) imported.`;
    await reload();
  };

  onDelegate(container, "click", "#dr-import", async () => {
    const caseId = container.querySelector<HTMLSelectElement>("#dr-case")?.value ?? "";
    const roomId = container.querySelector<HTMLSelectElement>("#dr-room")?.value || null;
    const files = Array.from(container.querySelector<HTMLInputElement>("#dr-files")?.files ?? []);
    if (!caseId) {
      s.status = "Select a case before importing photos.";
      await reload();
      return;
    }
    if (files.length === 0) {
      s.status = "Select at least one image.";
      await reload();
      return;
    }
    await importPhotos(files, caseId, roomId);
  });

  // Camera capture (§11): obtained via getUserMedia when the browser allows it.
  onDelegate(container, "click", "#dr-capture", async () => {
    const caseId = container.querySelector<HTMLSelectElement>("#dr-case")?.value ?? "";
    const roomId = container.querySelector<HTMLSelectElement>("#dr-room")?.value || null;
    if (!caseId) {
      s.status = "Select a case before capturing.";
      await reload();
      return;
    }
    if (!navigator.mediaDevices?.getUserMedia) {
      s.status = "This browser cannot access a camera. Use Import Photo instead.";
      await reload();
      return;
    }
    let stream: MediaStream | null = null;
    try {
      stream = await navigator.mediaDevices.getUserMedia({ video: true });
      const video = document.createElement("video");
      video.srcObject = stream;
      await video.play();
      await new Promise((resolve) => setTimeout(resolve, 350)); // allow exposure/focus
      const canvas = document.createElement("canvas");
      canvas.width = video.videoWidth || 1280;
      canvas.height = video.videoHeight || 720;
      canvas.getContext("2d")?.drawImage(video, 0, 0, canvas.width, canvas.height);
      const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob((b) => resolve(b), "image/png"));
      if (!blob) throw new Error("the captured frame could not be encoded");
      const name = `camera_${Date.now()}.png`;
      await importPhotos([new File([blob], name, { type: "image/png" })], caseId, roomId);
      s.status = "Camera photo captured and saved.";
    } catch (err) {
      const message = (err as { name?: string }).name === "NotAllowedError"
        ? "Camera permission was denied. Use Import Photo instead."
        : `Camera capture failed: ${(err as Error).message}`;
      s.status = message;
    } finally {
      if (stream) for (const track of stream.getTracks()) track.stop();
      await reload();
    }
  });

  const redraw = () => {
    const canvas = container.querySelector<HTMLCanvasElement>("#dr-preview");
    const ctx = canvas?.getContext("2d");
    if (!canvas || !ctx || !s.image || !s.image.complete) return;
    const scale = Math.min(canvas.width / s.image.naturalWidth, canvas.height / s.image.naturalHeight);
    const w = Math.max(1, Math.floor(s.image.naturalWidth * scale));
    const h = Math.max(1, Math.floor(s.image.naturalHeight * scale));
    canvas.width = w;
    canvas.height = h;
    ctx.drawImage(s.image, 0, 0, w, h);
    applyPhotoAdjustments(ctx, w, h, {
      brightness: s.brightness,
      contrast: s.contrast,
      blackAndWhite: s.blackAndWhite,
    });
  };

  onDelegate(container, "input", "#dr-brightness", (el) => {
    s.brightness = Number((el as HTMLInputElement).value);
    const label = container.querySelector<HTMLElement>("#dr-brightness-value");
    if (label) label.textContent = s.brightness.toFixed(2);
    redraw();
  });
  onDelegate(container, "input", "#dr-contrast", (el) => {
    s.contrast = Number((el as HTMLInputElement).value);
    const label = container.querySelector<HTMLElement>("#dr-contrast-value");
    if (label) label.textContent = s.contrast.toFixed(2);
    redraw();
  });
  onDelegate(container, "change", "#dr-bw", (el) => {
    s.blackAndWhite = (el as HTMLInputElement).checked;
    redraw();
  });
  onDelegate(container, "click", "#dr-reset-adjust", () => {
    s.brightness = BRIGHTNESS_RANGE.default;
    s.contrast = CONTRAST_RANGE.default;
    s.blackAndWhite = false;
    void reload();
  });

  onDelegate(container, "change", "#dr-findings", async (el) => {
    const checked = (el as HTMLInputElement).checked;
    const id = container.querySelector<HTMLElement>("[data-photo-editor]")?.dataset.photoEditor;
    if (!id) return;
    const record = await db().evidence.get(id);
    if (!record) return;
    await db().evidence.put({
      ...record,
      reviewStatus: checked ? "flagged" : "raw",
      updatedAt: Date.now(),
    });
    const audit = new AuditService(db());
    await audit.record("evidenceReviewUpdated", checked ? "Photo flagged as Included in Findings." : "Photo flag cleared.", {
      caseId: record.caseId,
      affectedRecordId: id,
      metadata: { flagged: checked },
    });
    s.status = checked ? "Photo included in findings." : "Photo flag cleared.";
    await reload();
  });

  onDelegate(container, "click", "#dr-save-notes", async () => {
    const id = container.querySelector<HTMLElement>("[data-photo-editor]")?.dataset.photoEditor;
    const notes = container.querySelector<HTMLTextAreaElement>("#dr-notes")?.value ?? "";
    if (!id) return;
    const record = await db().evidence.get(id);
    if (!record) return;
    await db().evidence.put({ ...record, notes, updatedAt: Date.now() });
    s.notes = notes;
    s.status = "Notes saved.";
    await reload();
  });

  onDelegate(container, "click", "#dr-save-derivative", async () => {
    const id = container.querySelector<HTMLElement>("[data-photo-editor]")?.dataset.photoEditor;
    if (!id || !s.image) return;
    const record = await db().evidence.get(id);
    const canvas = container.querySelector<HTMLCanvasElement>("#dr-preview");
    if (!record || !canvas) return;
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob((b) => resolve(b), "image/png"));
    if (!blob) {
      s.status = "The adjusted copy could not be encoded.";
      await reload();
      return;
    }
    const repo = new EvidenceRepository(db());
    const baseName = (record.originalFileName ?? record.fileName).replace(/\.[^.]+$/, "");
    const fileName = `${baseName}-adjusted.png`;
    const derived = await repo.createDerived({
      sourceId: record.id,
      mediaType: "photo",
      title: `${record.title} — adjusted`,
      fileName,
      data: new Blob([blob], { type: "image/png" }),
    });
    await db().evidence.put({
      ...derived,
      originalFileName: fileName,
      sourceDescription: `Derived from ${record.originalFileName ?? record.fileName}`,
      importedAt: Date.now(),
      verificationStatus: "verified",
      verifiedAt: Date.now(),
      verificationDetail: "Rendered from the preview and hashed on write.",
      roomId: record.roomId ?? null,
      captureTimestamp: Date.now(),
      captureTimestampSource: "investigator",
      derivationMethod: "dark-room-adjustment",
      derivationParameters: {
        sourceEvidenceId: record.id,
        brightness: s.brightness,
        contrast: s.contrast,
        blackAndWhite: s.blackAndWhite,
      },
      notes: `Dark Room adjustments — brightness ${s.brightness.toFixed(2)}, contrast ${s.contrast.toFixed(2)}${s.blackAndWhite ? ", black & white" : ""}. Source: ${record.originalFileName ?? record.fileName}`,
    });
    const audit = new AuditService(db());
    await audit.record("evidenceProcessed", "Dark Room adjusted copy saved as derived evidence.", {
      caseId: record.caseId,
      affectedRecordId: derived.id,
      metadata: { parentId: record.id, brightness: s.brightness, contrast: s.contrast, blackAndWhite: s.blackAndWhite },
    });
    s.status = `Saved adjusted copy "${fileName}" — the original photo is unchanged.`;
    await reload();
  });

  // Photo list "Open" buttons.
  onDelegate(container, "click", "[data-open-photo]", (el) => {
    s.selectedId = el.dataset.openPhoto ?? null;
    void reload();
  });
}
